SELECT item_id, content, occurred_at FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY item_id ORDER BY occurred_at DESC, id DESC) AS row_num FROM work_log) ranked WHERE row_num = 1 AND item_id IN
#{itemId}
ORDER BY item_id, occurred_at DESC

SELECT item_id, activity_type, occurred_at FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY item_id ORDER BY occurred_at DESC, id DESC) AS row_num FROM item_activity) ranked WHERE row_num = 1 AND item_id IN
#{itemId}
ORDER BY item_id, occurred_at DESC

SELECT membership.project_id, COUNT(*) AS cnt FROM item JOIN ON membership.item_id = item.id WHERE planned_date = #{today} AND status NOT IN ('DONE', 'CANCELLED') AND membership.project_id IN
#{projectId}
GROUP BY membership.project_id

SELECT 
FROM item
WHERE next_follow_up_at >= #{todayStart}
  AND next_follow_up_at < #{todayEnd}
  AND status NOT IN ('DONE', 'CANCELLED')
ORDER BY next_follow_up_at ASC

SELECT 
FROM item
WHERE next_follow_up_at >= #{from}
  AND next_follow_up_at < #{to}
  AND status NOT IN ('DONE', 'CANCELLED')
ORDER BY next_follow_up_at ASC

SELECT membership.project_id, status, COUNT(*) AS cnt, MAX(updated_at) AS last_at FROM item JOIN ON membership.item_id = item.id WHERE membership.project_id IN
#{projectId}
GROUP BY membership.project_id, status
